// === Tab: Sketch ===
// By Roni Kaufman
// Inspired by https://p5art.tumblr.com/image/175770708533
// and by Teddy Newton's Pixar short film "Day & Night" (2010)

var count = 0;
var maxCount = 100;
var incr = 0.3; // count increment
var ascending = true;

var size = 400; // real size of the sketch
var frontLayer; // p5.Graphics object used to separate the screen in two

var wave = (x) => (cos(x*PI)+1)/2;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(51);
  colorMode(HSB, 255);
  imageMode(CENTER); frontLayer = createGraphics(size, size);
  frontLayer.background(51);
  frontLayer.colorMode(HSB, 255);
}

function draw() {
  let percent = wave(count / maxCount);
  push();
  render(percent, this);
  pop();
  render(1 - percent, frontLayer);
  frontLayer.erase();
  frontLayer.noStroke();
  frontLayer.rect(0, 0, size/2, size);
  frontLayer.noErase();
  image(frontLayer, size/2, size/2);

  if (ascending) {
    count += incr;
  } else {
    count -= incr;
  }

  if (count > maxCount) {
    ascending = false;
  }
  if (count < 0) {
    ascending = true;
  }
}

function render(percent, img) {
  let radius = percent * size/3 + size/6;
  let biggerRadius = radius * 1.7;

  this.translate((width - size)/2, (height - size)/2);
  drawSquare(percent, img);
  drawCircle(percent, radius, img);
  drawLines(percent, biggerRadius, img);
}

function drawSquare(percent, img) {
  img.noStroke();
  img.fill(135, 240, 100 + percent*140);
  img.square(0, 0, size);
}

function drawCircle(percent, r, img) {
  img.fill(percent*39, percent*250, 140 + percent*115);
  img.circle(size/2, size/2, r);
}

function drawLines(percent, r, img) {
  img.stroke(225 + percent*30);
  img.strokeWeight(8);
  let margin = 25;
  let smallWidth = size - 2*margin;
  let nLines = 25; // number of lines
  for (let i = 0; i <= smallWidth; i += (Math.max(0.001, Math.abs(smallWidth/nLines)) || 1)) {
    let x = margin;
    let y = margin + i;
    while ((dist(x, y, size/2, size/2) > r/2) && (x < size - margin)) {
      x += 0.5;
    } 
    img.line(margin, y, x, y);
    if (x < size - margin) { // finish the bottom
      img.line(size - margin, y, size - x, y);
    }
  }
}
